        for i, ex in enumerate(c["examples"]):
            req(len(ex) >= 60, "شاهد قصير في " + cid + " موضع " + str(i) + ": " + str(len(ex)))
        req(len(c["example"]) <= 130, "جملة الخلاصة تتجاوز الحد في " + cid + ": " + str(len(c["example"])))
        pool += [c["explanation"], c["example"]] + c["examples"]

